import {icon,esc,count,stamp,button,head,rowRefs,empty,graph,towerPlot} from './case-ui.js';
export const sections = {
  overview:['Case overview','overview','A working view of the evidence, connections and leads in this case.'],
  sources:['Evidence library','evidence','Inspect source files, import quality and original records.'],
  network:['Link analysis','network','Explore recorded connections and the rows behind each relationship.'],
  towers:['Tower timeline','towers','Inspect tower observations by time and party. All times are IST.'],
  devices:['Devices & IP sessions','devices','Review recorded device identifiers and IP session metadata.'],
  assistant:['Case assistant','assistant','Ask about the open case and inspect the evidence behind each answer.'],
  reports:['Reports & audit','reports','Review saved findings and record a sign-off before printing a report.']
};
export function shell(view, cases, c, local=true) {
  const section=(key,label,items)=>`<div class="nav-group"><p>${label}</p>${items.map(id=>`<a href="#${id}" class="nav-item ${view===id?'selected':''}" ${view===id?'aria-current="page"':''}>${icon(sections[id][1],18)}<span>${sections[id][0]}</span></a>`).join('')}</div>`;
  return {
    side:`<a href="./index.html" class="brand"><span class="brandmark">${icon('logo',30)}</span><span>TRACE<span class="brand-x">−X</span></span></a><div class="nav-area">${section('case','WORKSPACE',['overview','sources','network','towers','devices'])}${section('tools','INVESTIGATION',['assistant','reports'])}</div><div class="side-foot">${icon(local?'database':'lock',17)}<span>${local?'Device workspace':'Shared workspace'}</span><a href="./index.html">Website</a></div>`,
    top:`<div class="crumb"><button class="mobile-menu icon-button" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><span class="crumb-icon">${icon('case',17)}</span><span>Workspace</span><i>/</i><strong>${esc(sections[view][0])}</strong></div><div class="case-control"><label for="switch-case">Active case</label><span class="select-wrap"><select id="switch-case" aria-label="Switch active case">${cases.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}<option value="__new__">+ Create case</option></select>${icon('chevron',16)}</span></div>`
  };
}
function metric(label,value,sub,ico,cls='') {
  return `<div class="metric"><div class="metric-label">${esc(label)}${icon(ico,17)}</div><strong class="${cls}">${count(value)}</strong><span>${esc(sub)}</span></div>`;
}
function caseTags(c) {
  return `<div class="case-meta"><span class="case-id">${esc(c.id)}</span><i></i><span>${esc(c.name)}</span>${c.id==='CASE-RJ-001'?'<span class="sample-tag">Synthetic case</span>':''}</div>`;
}
function fileList(c,limit=Infinity) {
  return c.files.length?`<div class="file-list">${c.files.slice(-limit).reverse().map(f=>`<button class="file-entry" data-action="file" data-value="${esc(f.id)}"><span class="file-icon">${icon('file',19)}</span><span class="file-entry-name"><strong>${esc(f.name)}</strong><small>${esc(f.type)} · ${count(f.qa.accepted)} accepted · ${count(f.qa.duplicate)} duplicates</small></span><span class="file-link">Inspect</span></button>`).join('')}</div>`:empty('No source files','Import CDR, IPDR or tower CSV files to start the case.');
}
function recordTable(rows) {
  if(!rows.length) return empty('No matching records','Import records or choose a different filter.');
  return `<div class="table-scroll"><table><thead><tr><th>Record</th><th>Type</th><th>Party</th><th>Counterparty / IP</th><th>Time · IST</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${button(r.id,'row',r.id,'cite')}</td><td>${esc(r.kind)}</td><td>${esc(r.from||'—')}</td><td>${esc(r.to||r.ip||'—')}</td><td>${esc(stamp(r.time,true))}</td></tr>`).join('')}</tbody></table></div>`;
}
function leadList(a) {
  return a.leads.length?`<div class="lead-list">${a.leads.slice(0,4).map(l=>`<button data-action="lead" data-value="${esc(l.id)}"><span class="lead-pin">${icon('network',17)}</span><span><strong>${esc(l.title)}</strong><small>${count(l.ids.length)} source record${l.ids.length===1?'':'s'}</small></span><span class="lead-view">View</span></button>`).join('')}</div>`:empty('No leads yet','Leads appear when the case records support a relationship or pattern.');
}
export function overview(c,a) {
  return `<div class="metrics">${metric('Total records',a.total,`${a.cdrCount} CDR / ${a.ipdrCount} IPDR`,'database')}${metric('Contact parties',a.contacts,`${a.edges.length} recorded links`,'network')}${metric('Source files',c.files.length,'SHA-256 fingerprinted','evidence')}${metric('Analytical leads',a.leads.length,'Available for review','pulse','orange')}</div><div class="overview-grid"><section class="panel net-panel">${head('Contact network','Observed links in the call records.',button('Explore','nav','network','text-button'))}${graph(a)}<div class="graph-foot"><span><i class="dot-orange"></i>Focus party</span><span><i class="dot-blue"></i>Contact</span><small>Select a node to inspect</small></div></section><section class="panel lead-panel">${head('Case leads', 'Patterns linked to original records.')}${leadList(a)}<div class="ask-shortcut"><span class="assistant-icon">${icon('assistant',18)}</span><div><strong>Case assistant</strong><p>Ask a question about these records.</p></div>${button('Ask','nav','assistant','text-button')}</div></section><section class="panel recent-panel">${head('Source files','Original imports and validation results.',button('View library','nav','sources','text-button'))}${fileList(c,3)}</section><section class="panel">${head('Recent activity','Latest actions in this workspace.')}${auditList(c,3)}</section></div>`;
}
export function sources(c,a,state) {
  const filter=state.search.trim().toLowerCase();
  const rows=c.records.filter(r=>[r.id,r.kind,r.from,r.to,r.cell,r.ip,r.imei,r.imsi].some(v=>String(v||'').toLowerCase().includes(filter)));
  return `<section class="panel">${head('Imported files','Select a file to view its hash and row-level quality checks.')}${fileList(c)}</section><section class="panel gap">${head('Normalized records','Select a record ID to open its original source rows.')}<form data-form="search" class="search-line"><label for="row-search">Search records</label><input id="row-search" name="query" type="search" value="${esc(state.search)}" placeholder="Record ID, party, cell or IP"><button class="button">Search</button>${filter?button('Clear','clear-search','','text-button'):''}</form>${recordTable(rows.slice(state.offset,state.offset+30))}<div class="paginator"><span>${rows.length?`${state.offset+1}–${Math.min(rows.length,state.offset+30)} of `:''}${count(rows.length)} records</span><div>${state.offset>0?button('Previous','page',Math.max(0,state.offset-30),'button small'):''}${rows.length>state.offset+30?button('Next','page',state.offset+30,'button small'):''}</div></div></section>`;
}
export function network(c,a,state) {
  const selected=a.nodes.find(n=>n.id===state.node);
  const edges=a.edges.filter(e=>!selected||e.source===selected.id||e.target===selected.id).sort((x,y)=>y.count-x.count);
  return `<section class="panel">${head('Contact network','Select a node to inspect its recorded links.')}${graph(a,state.node)}<div class="graph-foot"><span><i class="dot-orange"></i>Focus party</span><span><i class="dot-blue"></i>Contact</span><small>Up to 10 visible parties</small></div></section><section class="panel gap">${head(selected?'Connections for '+selected.id:'Recorded connections','Counts reflect communication events in the imported files.',selected?button('All connections','all-nodes','','text-button'):'')}<div class="table-scroll"><table><thead><tr><th>Party</th><th>Connected party</th><th>Records</th><th>Evidence</th></tr></thead><tbody>${edges.slice(0,state.edgeLimit).map(e=>`<tr><td>${esc(e.source)}</td><td>${esc(e.target)}</td><td>${count(e.count)}</td><td>${button('Inspect rows','rows',JSON.stringify(e.ids),'cite')}</td></tr>`).join('')}</tbody></table></div>${!edges.length?empty('No connections','Import CDR files to view communication links.'):''}${edges.length>state.edgeLimit?`<div class="paginator">${button('Show more connections','more-edges','','button small')}</div>`:''}</section>`;
}
export function towers(c,a,state) {
  const parties=[...new Set(a.timeline.map(e=>e.subject).filter(Boolean))];
  const timeline=a.timeline.filter(e=>!state.towerSubject||e.subject===state.towerSubject);
  return `<section class="panel">${head('Tower observations','Markers show recorded cell sites. A device location is approximate.')}<div class="select-line"><label for="tower-subject">Party</label><select id="tower-subject"><option value="">All parties</option>${parties.map(p=>`<option ${p===state.towerSubject?'selected':''}>${esc(p)}</option>`).join('')}</select></div>${towerPlot(timeline)}</section><section class="panel gap">${head('Observation timeline','Chronological records for the selected party.')}${timeline.length?`<div class="table-scroll"><table><thead><tr><th>Time · IST</th><th>Party</th><th>Tower / cell</th><th>Source</th></tr></thead><tbody>${timeline.slice(0,state.timelineLimit).map(e=>`<tr><td>${stamp(e.time)}</td><td>${esc(e.subject)}</td><td><strong>${esc(e.name || e.cell)}</strong><small>${esc(e.cell)}</small></td><td>${button(e.recordId,'row',e.recordId,'cite')}</td></tr>`).join('')}</tbody></table></div>`:empty('No tower observations','Import CDR or IPDR records containing cell identifiers.')}${timeline.length>state.timelineLimit?`<div class="paginator">${button('Show more observations','more-timeline','','button small')}</div>`:''}</section>`;
}
export function devices(c,a,state) {
  const sessions=c.records.filter(r=>r.kind==='IPDR');
  let pairs=a.devices;
  return `<section class="panel">${head('Device observations','Recorded IMEI and SIM identifiers for each party.')}${pairs.length?`<div class="table-scroll"><table><thead><tr><th>Party</th><th>IMEI / device</th><th>IMSI / SIM</th><th>Observed · IST</th><th>Source</th></tr></thead><tbody>${pairs.slice(0,state.deviceLimit).map(d=>`<tr><td>${esc(d.subject)}</td><td>${esc(d.imei||'—')}</td><td>${esc(d.imsi||'—')}</td><td>${stamp(d.time,true)}</td><td>${button(d.recordId,'row',d.recordId,'cite')}</td></tr>`).join('')}</tbody></table></div>`:empty('No device observations','Import records with an IMEI or IMSI field.')}${pairs.length>state.deviceLimit?button('Show more devices','more-devices','','button small'):''}</section><section class="panel gap">${head('IP sessions','Public addresses can be shared. Examine time, port and protocol together.')}${sessions.length?`<div class="table-scroll"><table><thead><tr><th>Observed · IST</th><th>Subscriber</th><th>IP / port</th><th>Protocol</th><th>Source</th></tr></thead><tbody>${sessions.slice(0,state.ipLimit).map(r=>`<tr><td>${stamp(r.time,true)}</td><td>${esc(r.from||'—')}</td><td>${esc(r.ip||'Unknown')} / ${esc(r.port||'Port missing')}</td><td>${esc(r.protocol||'Unknown')}</td><td>${button(r.id,'row',r.id,'cite')}</td></tr>`).join('')}</tbody></table></div>`:empty('No IP sessions','Import an IPDR file to inspect available session metadata.')}${sessions.length>state.ipLimit?button('Show more sessions','more-ip','','button small'):''}</section>`;
}
export const promptsDemo=['Which contacts do A and B share?','Did A call B directly?','Show tower timeline for A','Show device changes for A','Who are the most frequent contacts?'];
export function assistant(c,a,state) {
  const history=c.chat||[];
  const prompts = c.subjects?.length>=2 ? [`Which contacts do ${c.subjects[0]} and ${c.subjects[1]} share?`,`Did ${c.subjects[0]} call ${c.subjects[1]} directly?`,`Show tower timeline for ${c.subjects[0]}`,'Who are the most frequent contacts?'] : ['Who are the most frequent contacts?',...a.nodes.slice(0,1).map(n=>'Show tower timeline for '+n.id)];
  return `<div class="assistant-layout"><section class="panel chat"><div class="assistant-head"><span class="assistant-symbol">${icon('assistant',25)}</span><div><h2>Evidence-linked assistant</h2><p>Deterministic case queries · source-cited answers</p></div></div><div class="chat-thread">${history.length?history.slice(-20).map((item,i)=>`<article class="exchange"><div class="user-question"><small>QUESTION</small><p>${esc(item.question)}</p></div><div class="answer"><small>${item.supported?'EVIDENCE-LINKED ANSWER':'INSUFFICIENT EVIDENCE'}</small><p>${esc(item.text)}</p>${rowRefs(item.ids)}${item.suggestion?('<div class="suggestion"><p>Did you mean this question?</p>'+button(item.suggestion,'prompt',item.suggestion,'prompt')+'</div>'):''}${item.supported&&item.ids?.length?button('Save finding','save-chat',item.id,'text-button','bookmark'):''}</div></article>`).join(''):`<div class="chat-intro">${icon('network',34)}<h3>What do the records show?</h3><p>Ask about shared contacts, device changes or tower observations in ${esc(c.name)}.</p></div>`}</div><form data-form="ask" class="ask-form"><label for="case-question">Ask a case question</label><div><input id="case-question" name="question" required maxlength="400" autocomplete="off" placeholder="Ask about these records…"><button class="button primary">${icon('send',16)}Ask</button></div></form></section><section class="panel suggested">${head('Suggested questions','Run a question against this case.')}<div>${prompts.map(p=>button(p,'prompt',p,'prompt')).join('')}</div></section></div>`;
}
export function auditList(c,limit) {
  const list=(c.audit || []).slice(-limit).reverse();
  return list.length?`<ol class="activity">${list.map(e=>`<li><i></i><div><strong>${esc(e.action)}</strong><p>${esc(e.detail)}</p><time>${stamp(e.time)}</time></div></li>`).join('')}</ol>`:empty('No activity yet','Case actions will appear here.');
}
export function reviewed(c){return !!c.review && c.review.revisionKey===(c.contentVersion||0);}
export function reports(c,a,state) {
  const findings=c.findings||[], signed=reviewed(c);
  return `<section class="panel">${head('Case report',`${count(findings.length)} saved finding${findings.length===1?'':'s'} · ${signed?'Signed by '+c.review.reviewer:'Awaiting review'}`,signed?button('Print / save PDF','print','','button primary','print'):button('Review & sign','review','','button primary','check'))}${findings.length?`<div class="report-findings">${findings.map(f=>`<article><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p>${rowRefs(f.ids)}</article>`).join('')}</div>`:empty('No saved findings','Open a case lead or an evidence-linked answer, then choose Save finding.')}${signed?`<p class="panel-note">Signed ${stamp(c.review.signedAt)} IST. Changes to evidence or findings require a new review.</p>`:''}</section><section class="panel gap">${head('Activity log','Case actions in reverse chronological order.')}${auditList(c,state.auditLimit)}${c.audit?.length>state.auditLimit?button('Show earlier actions','more-audit','','button small'):''}</section>`;
}
export function pageHeader(view,c) {
  return `<header class="page-header"><div>${caseTags(c)}<h1>${esc(sections[view][0])}</h1><p>${esc(sections[view][2])}</p></div><div class="page-actions">${view==='overview'||view==='sources'?button('Import evidence','import','','button primary','upload'):''}</div></header>`;
}
